/* Host-side unit test for the shim: includes prx.c directly so the static
 * helpers can be called. Usage: shim_unit ROOTDIR  (needs ROOTDIR/etc/{passwd,group}
 * as generated by tests/smoke.sh). Exit status is a bitmask of failed checks. */
#include "../src/prx.c"
extern int printf(const char*, ...);

int main(int argc, char**argv) {
    int bad = 0;
    if (argc < 2) return 255;
    memcpy(g_root, argv[1], strlen(argv[1])+1);
    g_rl = strlen(argv[1]);

    /* group with 300 members (was truncated at 32) in a >48 KiB /etc/group */
    if (gr_lookup_dyn("big", 0, 0) != 1) bad |= 1;
    else {
        int m = 0;
        while (s_gr.mem[m]) m++;
        if (m != 300 || strcmp(s_gr.mem[299], "user299")) bad |= 2;
    }
    if (gr_lookup_dyn("last", 0, 0) != 1 || s_gr.gid != 5001) bad |= 4;
    /* entry located past 48 KiB in /etc/passwd */
    if (pw_lookup_dyn(0, 1, 99999) != 1 || strcmp(s_pw.name, "lastuser")) bad |= 8;
    /* membership scan used for initgroups-style emulation */
    u32 out[NVG];
    if (cr_collect("user299", 100, out, NVG) != 2 || out[1] != 5000) bad |= 16;

    /* IPv6 literal parser */
    u8 a[16];
    if (!parse_v6("2001:db8::1", 11, a) || a[0] != 0x20 || a[1] != 0x01 || a[15] != 1) bad |= 32;
    if (!parse_v6("::ffff:1.2.3.4", 14, a) || a[10] != 0xff || a[12] != 1 || a[15] != 4) bad |= 64;
    if (!parse_v6("::", 2, a) || !parse_v6("1:2:3:4:5:6:7:8", 15, a)) bad |= 128;
    if (parse_v6("1::2::3", 7, a) || parse_v6("12345::", 7, a) || parse_v6("1:2:3:4:5:6:7", 13, a)
        || parse_v6("fe80::1%eth0", 12, a) || parse_v6(":1", 2, a)) bad |= 256;

    /* binfmt_misc: register-line parser, matcher, rule database */
    struct bfrule r;
    if (bf_parse(":n:M:1:AB:\\xff\\xdf:/usr/bin/i:PF\n", strlen(":n:M:1:AB:\\xff\\xdf:/usr/bin/i:PF\n"), &r) != 0 || strcmp(r.name, "n") || r.type != 'M' || r.off != 1
        || r.msz != 2 || r.magic[0] != 'A' || r.mask[1] != 0xdf || !r.hasmask || r.flags != (BF_P|BF_F) || strcmp(r.interp, "/usr/bin/i")) bad |= 512;
    if (bf_parse(";e;E;;py;;/usr/bin/py;O", strlen(";e;E;;py;;/usr/bin/py;O"), &r) != 0 || r.type != 'E' || r.msz != 2 || memcmp(r.magic, "py", 2)) bad |= 512;
    if (bf_parse(":n:M::\\x7fELF::/i:C", strlen(":n:M::\\x7fELF::/i:C"), &r) != 0 || r.msz != 4 || r.magic[0] != 0x7f || r.hasmask || r.mask[3] != 0xff || r.flags != (BF_C|BF_O)) bad |= 512;
    {
        static const char*const badreg[] = {
            ":a/b:M::X::/i:", ":register:M::X::/i:", ":..:M::X::/i:", ":a:Q::X::/i:", ":a:M:256:X::/i:", ":a:M:255:XY::/i:",
            ":a:M::XY:\\xff:/i:", ":a:M::X::/i:Z", ":a:M::::/i:", ":a:M::X::/i", ":a:E:1:x::/i:", ":a:E::x/y::/i:", ":a:M::X::/i j:", ":a:M::\\x4::/i:", "\\a\\M\\\\X\\\\/i\\",
        };
        for (unsigned i = 0; i<sizeof badreg/sizeof*badreg; i++) if (bf_parse(badreg[i], strlen(badreg[i]), &r) == 0) bad |= 1024;
    }
    {
        g_nbf = 0;
        g_bfst = 1;
        char txt[] = ":low:M::PK::/bin/zip:\n:high:M::PKZ::/bin/zip2:O\n:py:E::py::/bin/py:\n:low:M::QQ::/bin/dup:\n:bad\n";
        if (bf_register_text(txt) != 3 || g_nbf != 3) bad |= 2048;
        const u8 pk[] = {'P', 'K', 'Z', 0};
        const struct bfrule*m = bf_find(pk, 4, "/tmp/a.bin");
        if (!m || strcmp(m->name, "high")) bad |= 2048;          /* newest matching rule wins */
        m = bf_find(pk, 2, "/tmp/a.bin");
        if (!m || strcmp(m->name, "low")) bad |= 2048;
        m = bf_find((const u8*) "xx", 2, "/home/u.d/run.py");
        if (!m || strcmp(m->name, "py")) bad |= 2048;
        if (bf_find((const u8*) "xx", 2, "/home/u.py/run") || bf_find((const u8*) "xx", 2, "/tmp/py")) bad |= 2048;
        m = bf_find(pk, 3, "/bin/zip2");
        if (!m || !strcmp(m->name, "high")) bad |= 2048;         /* a rule never re-enters its own interpreter */
        g_bfr[1].enabled = 0;
        m = bf_find(pk, 4, "/tmp/a.bin");
        if (!m || strcmp(m->name, "low")) bad |= 2048;
        g_bfst = 0;
        if (bf_find(pk, 4, "/tmp/a.bin")) bad |= 2048;           /* status 0 disables everything */
        g_bfst = 1;
        /* database round trip */
        static char db[8192];
        size_t dn = bf_db_text(db, sizeof db);
        int n0 = g_nbf;
        g_nbf = 0;
        bf_db_parse(db);
        if (dn == 0 || g_nbf != n0 || strcmp(g_bfr[1].name, "high") || g_bfr[1].enabled || g_bfr[1].flags != BF_O || g_bfr[2].type != 'E') bad |= 4096;
        char fm[512];
        bf_fmt(&g_bfr[0], fm, sizeof fm);
        if (strcmp(fm, "enabled\ninterpreter /bin/zip\nflags: \noffset 0\nmagic 504b\n")) bad |= 4096;
        if (bf_cmd("0\n", 2) != 0 || bf_cmd("1", 1) != 1 || bf_cmd("-1\n", 3) != 2 || bf_cmd("-1", 2) != 2 || bf_cmd("2", 1) != -1 || bf_cmd(":x:", 3) != -1) bad |= 4096;
    }
    /* live sync against a directory laid out like the one prx creates */
    if (argc > 2) {
        char p[PM];
        char sb[64];
        long n;
        memcpy(g_bfdir, argv[2], strlen(argv[2])+1);
        g_nbf = 0;
        bf_path(p, "/fs/register", NULL);
        bf_spit(p, ":a:M::XY::/bin/i:\n:b:E::zz::/bin/j:P\n", strlen(":a:M::XY::/bin/i:\n:b:E::zz::/bin/j:P\n"));
        bf_sync();
        if (g_nbf != 2 || bf_fsize(p) != 0) bad |= 8192;
        bf_path(p, "/fs/a", NULL);
        if (bf_slurp(p, sb, sizeof sb) < 10 || strncmp(sb, "enabled\ninterp", 14)) bad |= 8192;
        bf_spit(p, "0\n", 2);
        bf_sync();
        if (g_nbf != 2 || g_bfr[0].enabled || bf_slurp(p, sb, sizeof sb) < 10 || strncmp(sb, "disabled\n", 9)) bad |= 16384;
        bf_spit(p, "-1\n", 3);
        bf_sync();
        if (g_nbf != 1 || strcmp(g_bfr[0].name, "b") || bf_fsize(p) >= 0) bad |= 16384;
        bf_path(p, "/fs/status", NULL);
        bf_spit(p, "0", 1);
        bf_sync();
        if (g_bfst != 0 || (n = bf_slurp(p, sb, sizeof sb)) < 8 || strncmp(sb, "disabled\n", 9)) bad |= 16384;
        bf_spit(p, "-1\n", 3);
        bf_sync();
        bf_path(p, "/fs/b", NULL);
        if (g_nbf != 0 || bf_fsize(p) >= 0) bad |= 16384;
        g_nbf = 0;
        bf_db_load();
        if (g_nbf != 0) bad |= 16384;                                 /* removal was persisted */
    }

    printf("%d\n", bad);
    return bad ? 1 : 0;
}
